package com.sleela.commonrails.heritage.printing;
import java.io.PrintWriter;import java.util.Locale;
public final class CommonRailsPrinting{private CommonRailsPrinting(){} public static final class PrintLayout{public static final int WIDTH=80,OBJECT_ID_WIDTH=10,CURRENT_WIDTH=39,SIDE=21,CELLS=441;private PrintLayout(){}} public enum PrintState{START,WORKING,PROGRESS,COMPLETE,WARN,ERROR} public static final class PrintGlyphs{public static final String FULL="█",EMPTY="░";private PrintGlyphs(){}} public static final class PrintField{public static String pad(String s,int w){return s.length()>=w?s:s+" ".repeat(w-s.length());}} public static final class PrintLine{public static void write(PrintWriter o,String s){int p=0;while(p<s.length()){int n=Math.min(80,s.length()-p);o.print(s.substring(p,p+n));o.print(" ".repeat(80-n));o.println();p+=n;while(p<s.length()&&s.charAt(p)==' ')p++;}}} public static final class PrintProgress{public static int clamp(int p){return Math.max(0,Math.min(100,p));}public static int cells(int p){return clamp(p)*441/100;}public static void write(PrintWriter o,int p){p=clamp(p);o.printf(Locale.ROOT,"  progress %d%% (%d/441 cells)%n",p,cells(p));}} public static final class PrintComponent{public static void write(PrintWriter o,String n,long id,long d,String m){PrintLine.write(o,String.format(Locale.ROOT,"-- : [Object ID: %010d] [Date: %d] [Current: @%s] . %s .",id,d,n,m));}} public static final class PrintFormatter{public static void status(PrintWriter o,PrintState s,String m){PrintLine.write(o,"["+s.name()+"] "+m);}} public static final class PrintRenderer{public static void square(PrintWriter o,int f){f=Math.max(0,Math.min(441,f));for(int r=0;r<21;r++){for(int c=0;c<21;c++){int i=(20-r)*21+(20-c);o.print(i<f?PrintGlyphs.FULL:PrintGlyphs.EMPTY);}o.println();}}} public static final class PrintWriterTarget{public final PrintWriter out;public PrintWriterTarget(PrintWriter o){out=o;}}}
